import { Observable } from 'rxjs';
import { SwapListPaginationOptions, SwapDetails, Wallet } from 'decentr-js';

import { DecentrNetworkId } from '@environments/environment.definitions';

interface CharonAPI {
  connect(): void;
  createSwap(receiverAddress: Wallet['address'], txHash: string, signature: string): Promise<SwapDetails>;
  getBalance(): Observable<string>;
  getChainId(): Observable<string>;
  getNetwork(): Observable<DecentrNetworkId>;
  getSwapList(paginationOptions?: SwapListPaginationOptions): Promise<SwapDetails[]>;
  getSwapById(swapId: SwapDetails['id']): Promise<SwapDetails>;
  getWalletAddress(): Observable<string>;
  isConnected(): Observable<boolean>;
  initSwapTransaction(address: string, amount: number): Promise<boolean>;
}

declare const window: any; // eslint-disable-line
export default window.charon as CharonAPI;
